// InputSpec gains nothing: both keys are read from StepConfig.Config directly,
// because they are step-author intent, not extractable inputs.

// Build spec JSONB: spec_data path result, then spec_paths, then spec_literal.
// Later layers win. Literals are last because they are the step author's most
// explicit statement of intent.
specMap := map[string]interface{}{}
if specData := inputs.GetMap("spec_data"); specData != nil {
	for k, v := range specData {
		specMap[k] = v
	}
}

// spec_paths: {"component_id": "update_result.component_id"} — each value is a
// path into collected data. A configured path that does not resolve is a hard
// error: the step author asked for this field, and silently omitting it is how
// bugs_open/024 stayed invisible for three cycles (a spec missing component_id
// makes create_rerender_items' scoped=false, which degrades the re-render to
// assemble-from-stale and still reports success).
if sp, ok := config["spec_paths"].(map[string]interface{}); ok {
	for key, rawPath := range sp {
		path, isStr := rawPath.(string)
		if !isStr || path == "" {
			return nil, fmt.Errorf("spec_paths[%q] must be a non-empty string path", key)
		}
		val := datahelpers.ExtractNestedField(params.CollectedData, path)
		if val == nil || val == "" {
			return nil, fmt.Errorf("spec_paths[%q]: path %q did not resolve; refusing to create a work item with an incomplete spec", key, path)
		}
		specMap[key] = val
	}
}

// spec_literal: {"reason": "section_data_resolved"} — verbatim, no resolution.
if sl, ok := config["spec_literal"].(map[string]interface{}); ok {
	for k, v := range sl {
		specMap[k] = v
	}
}

specJSON := "{}"
if len(specMap) > 0 {
	if b, err := json.Marshal(specMap); err == nil {
		specJSON = string(b)
	} else {
		return nil, fmt.Errorf("marshal spec: %w", err)
	}
}

// Build item_key from prefix + domain, optionally scoped by a resolved value.
itemKeyPrefix, _ := config["item_key_prefix"].(string)
var itemKey string
if itemKeyPrefix != "" {
	domain := inputs.Get("domain")
	if domain == "" {
		domain = siteID.String()[:8]
	}
	itemKey = fmt.Sprintf("%s_%s", itemKeyPrefix, domain)

	// Optional scoping suffix. '<prefix>_<domain>' is SITE-wide: two components
	// fixed close together on one site collide on idx_swi_dedup and one request
	// is lost. A step that knows what it is acting on names it here.
	// Additive by design — unset or unresolved leaves the key exactly as before.
	if f, ok := config["item_key_suffix_field"].(string); ok && f != "" {
		if sfx := datahelpers.ExtractNestedFieldString(params.CollectedData, f); sfx != "" {
			itemKey = fmt.Sprintf("%s_%s", itemKey, sfx)
		} else {
			logger.Warn("create_work_item: item_key_suffix_field did not resolve, key stays site-wide",
				zap.String("field", f), zap.String("item_key", itemKey))
		}
	}
}

// recurrence_expected: this item's RE-REQUEST is normal, not evidence that
// previous handlers failed. See workItem.recurrenceExpected. Default false.
recurrenceExpected, _ := config["recurrence_expected"].(bool)

// ... and in the workItem literal passed to insertWorkItem:
//     itemKey:            itemKey,
//     dependsOn:          dependsOn,
//     recurrenceExpected: recurrenceExpected,

// A tool section legitimately has NO content_data: a tool is self-contained
// HTML with no LLM-authored fields, so content_data={} is its correct shape,
// not evidence of the missing-content defect this pre-check exists to catch.
// Escalating it bypasses save_sections (the only writer of rendered_html), so
// the fix is computed and discarded — bugs_open/024.
// Keyed on the EXPLICIT marker, never on a heuristic about field shape.
isSelfContained := func(comp componentInfo, ok bool) bool {
	if !ok {
		return false
	}
	if len(comp.InputSchema) > 0 {
		return false
	}
	level, _ := comp.Raw["component_level"].(string)
	return level == "tool"
}

for _, s := range stored {
	comp, haveComp := schemas[s.slotName]
	if isSelfContained(comp, haveComp) {
		logger.Info("rerender_page_sections: self-contained tool section, no content_data expected — rendering from template",
			zap.String("page", pageName), zap.String("section", s.slotName))
		continue
	}
	reason := ""
	if len(s.contentData) == 0 {
		reason = "no stored content_data"
	} else if ok := haveComp; ok && len(comp.InputSchema) > 0 {
		if missing := missingRequiredLLMFields(comp.InputSchema, s.contentData); len(missing) > 0 {
			reason = fmt.Sprintf("stored content_data missing required field(s) %v", missing)
		}
	}
	// ... unchanged escalation below ...
}
